				FAIL("Invalid token");
			}
			break;

		case VARTYPE_PARAM:
			switch (curStatusPtr->curToken) {
			case TOK_SIGN:
				if ((curStatusPtr->curValue.newVar.state < 4) || (curStatusPtr->curValue.newVar.state > 10)
