				}

				if (curStatusPtr->curValue.newVar.state > 2) {
					size_t tokLen = getTokenLength(curStatusPtr);
					char *tok = (char*)malloc((tokLen + 2) * sizeof(char));
					copyToken(curStatusPtr, tok);
					tok[tokLen] = '.';
					tok[tokLen + 1] = '\0';
