					pushArray((sArray*)&curStatusPtr->curValue.newVar, strdup("0.0"));
					curStatusPtr->curValue.newVar.state += 2;
				}
				if (curStatusPtr->curValue.newVar.state == 9) {
					pushArray((sArray*)&curStatusPtr->curValue.newVar, strdup(","));
					pushArray((sArray*)&curStatusPtr->curValue.newVar, strdup("0.0"));
