			pushArray((sArray*)var, curStatusPtr->curValue.string);

			int ret;
			varIdx = kh_put(variables, curStatusPtr->varsMap, curStatusPtr->curValue.string, &ret);
			if (ret < 0) {
				FAIL("Unknown error");
			}
