			curStatusPtr->valueType = TYPE_NONE;
			}
			break;

		case TOK_WHITESPACE:
		case TOK_NEWLINE:
			break;

		case TOK_END_OF_INST:
			if (curStatusPtr->valueType == TYPE_NONE) {
