			case STATE_AFTER_VALID_LSQBR_ADOK: {
				char *faa = (char*)realloc(
					curVarPtr->floatArrAddr,
					(strlen(curVarPtr->floatArrAddr) + getTokenLength(curStatusPtr) + 1) * sizeof(char)
				);
