    }
    noerrorShimNoPurge();
    break_lockarrays(ATT_COLOR);
    clone_gl_pointer(glstate->vao->vertexattrib[ATT_COLOR], size, (type==GL_FLOAT)?GL_FALSE:GL_TRUE);
}
