                 (((GLuint)(color[2] * 31.0f) & 0x1f) << 10) |
                 (((GLuint)(color[1] * 31.0f) & 0x1f) << 5 ) |
                 (((GLuint)(color[0] * 31.0f) & 0x1f)      );
