        for (int i = 0; i < height; i++) {
			for (int j = 0; j < width; j++) {
				((char*)dst_pos)[0] = ((char*)src_pos)[3];
				((char*)dst_pos)[1] = ((char*)src_pos)[2];
				((char*)dst_pos)[2] = ((char*)src_pos)[1];
                ((char*)dst_pos)[3] = ((char*)src_pos)[0];
				src_pos += src_stride;
				dst_pos += dst_stride;
			}
			dst_pos += dst_width;
