                #else
                *(GLushort*)dst_pos = ((((int)byte_src[0])*77 + ((int)byte_src[1])*151 + ((int)byte_src[2])*28)&0xff00)>>8 | (byte_src[3]<<8);
                #endif
				src_pos += src_stride;
				dst_pos += dst_stride;
			}
			dst_pos += dst_width;
            src_pos += src_widthadj;
        }
