			for (int j = 0; j < width; j++) {
				((unsigned char*)dst_pos)[0] = ((unsigned char*)src_pos)[2];
				((unsigned char*)dst_pos)[1] = ((unsigned char*)src_pos)[1];
				((unsigned char*)dst_pos)[2] = ((unsigned char*)src_pos)[0];
