    // find type of obj (shader or program)
    program_t *glprogram = NULL;
    khint_t k_program;
    {
        khash_t(programlist) *programs = glstate->glsl->programs;
        k_program = kh_get(programlist, programs, obj);
        if (k_program != kh_end(programs))
