        if (face==GL_FRONT)
            gl4es_glStencilFunc(func, ref, mask);
        else
            noerrorShim();
    }
}
AliasExport(void,glStencilFuncSeparate,,(GLenum face, GLenum func, GLint ref, GLuint mask));

